-- 확인 (기대: chunk_rows 777 / total_rows 5483)
--   chunk_rows 가 기대보다 작으면 이 청크가 덜 들어간 것 — 다시 실행할 것.
--   total_rows 는 01_chunk_01 부터 순서대로 실행했을 때의 누적값이다.
SELECT count(*) FILTER (WHERE chunk_no = 7) AS chunk_rows,
       count(*)                                AS total_rows
